def _v1toks(s):
    return re.findall(r"[a-zA-Z']+", (s or '').lower())

def _v1gd(toks):
    if not toks:
        return 0.0
    return sum(1 for t in toks if t in GENERIC_VERBS) / len(toks)

def _v1vd(toks):
    if not toks:
        return 0.0
    return sum(1 for t in toks if t in VIVID_VERBS) / len(toks)

def _v1avglen(toks):
    content = [t for t in toks if len(t) > 3 and t not in GENERIC_VERBS]
    if not content:
        return 0.0
    return sum(len(t) for t in content) / len(content)

def scorer(text, anchor, params):
    toks_t = _v1toks(text)
    if len(toks_t) < 4:
        return 0.0
    toks_a = _v1toks(anchor) or toks_t
    gd_t = _v1gd(toks_t)
    gd_a = _v1gd(toks_a)
    vd_t = _v1vd(toks_t)
    len_t = _v1avglen(toks_t)
    len_a = _v1avglen(toks_a)
    gd_component = 0.5 + min(0.5, max(-0.5, (gd_a - gd_t) * 4.0))
    vivid_component = min(1.0, vd_t * 12.0)
    length_component = 0.5 + min(0.5, max(-0.5, (len_t - len_a) * 0.15))
    raw = 0.45 * gd_component + 0.30 * vivid_component + 0.25 * length_component
    return _clamp(raw)
